// 只核新100人真实输入的C边界与原调度尾；全链阶段与跨域原子性由中央生产Kernel另验。
#include "background_travel_support.hpp"
int main(int argc,char** argv){
    assert(argc==3);std::string root=argv[1];auto index=read_file(root+"/oracle-index.json");auto catalog=read_file(root+"/expanded-catalog.json");auto witness=read_file(argv[2]);auto& data=*catalog.find("data");auto common=std::make_shared<const CommonCatalog>(checked(decode_common_catalog(data)));auto ic=checked(decode_interaction_catalog(data,common));Integer boundaries=0,tails=0;
    for(auto& entry:*index.find("commands")->as<BoundaryValue::Array>()){
        auto file=boundary::get_string(*entry.find("after"),"file","after");auto source=read_file(root+"/"+file);auto scenario=boundary::get_string(source,"scenario_id","state");auto mc=checked(decode_military_catalog(data,scenario));auto tc=checked(decode_travel_catalog(data,scenario));auto m=checked(decode_military_seed(source));auto i=checked(decode_interaction_seed(source));auto t=checked(decode_travel_seed(source));CommonStore c(domain_common(source,*common),common);Services services(c,m,i,tc,ic);Access access(c,m,i,ic,*common);access.interaction.journey_encounter=[&](const StableId& id)->Outcome<std::pair<StableId,bool>>{auto p=t.actions.find(id);if(!p)return {false,{},common_failure("EncounterWithoutJourney").error};return {true,{p->encounter_id,p->paused},{}};};access.interaction.terrain_point_valid=[&](const StableId& map,const PointI& point){auto terrain_map=tc.maps.find(map);return terrain_map&&terrain::point_valid_prepared(*terrain_map,point,terrain::Mode::foot,{});};require(validate_military_state(c,m,mc,access.military));require(validate_interaction_state(c,i,ic,access.interaction));compare_fragment(source,checked(export_military_state(m)));compare_fragment(source,checked(export_interaction_state(i)));
        CodecVisitor::Buffer bytes;CodecVisitor writer(bytes);require(visit_military_checkpoint(writer,m));require(writer.finish());MilitaryState restored;CodecVisitor reader(static_cast<const CodecVisitor::Buffer&>(bytes));require(visit_military_checkpoint(reader,restored));require(reader.finish());equal(checked(export_military_state(m)),checked(export_military_state(restored)),"actual100 military checkpoint");++boundaries;
        auto hash=boundary::get_string(*entry.find("after"),"sha256","after");for(auto& expected:*witness.find("rows")->as<BoundaryValue::Array>()){if(boundary::get_string(expected,"state_sha256","witness")!=hash)continue;auto before_common=encode_common_state(c.state());auto before_military=checked(export_military_state(m));auto before_travel=checked(export_travel_state(t));auto proposals=checked(military_schedule_proposals(c,m,mc,*common,tc,access.interaction,c.state().metadata.player_actor_id));assert(proposals.empty()&&expected.find("proposals")->as<BoundaryValue::Array>()->empty());auto contacts=checked(probe_military_contacts(c,m,mc,t,tc,services));assert(contacts.ordered_hits.empty()&&expected.find("contacts")->as<BoundaryValue::Array>()->empty());assert(!mc.march_condition_model&&!*expected.find("march_enabled")->as<bool>());require(check_military_contact_capability(c,m,mc,t,tc,services));assert(m.arrival_facts.size()==1&&m.arrival_facts[0].id=="fact:369");equal(before_common,encode_common_state(c.state()),"actual100 read-only tail common");equal(before_military,checked(export_military_state(m)),"actual100 read-only tail military");equal(before_travel,checked(export_travel_state(t)),"actual100 read-only tail travel");++tails;}
    }
    assert(boundaries==15&&tails==2);std::cout<<"background_actual100: PASS (15 actual C boundaries/checkpoints; 2 original tick7/8 empty schedule/contact tails; arrival fact:369 retained)\n";
}
